}

.checkbox { display: inline-flex; gap: 10px; align-items: center; font-weight: 500; cursor: pointer; }

.errors {
  background: var(--c-pink);
  color: var(--c-white);
  border-radius: 12px;
  padding: 14px 18px;
  margin-bottom: 20px;
}
.errors ul { margin: 0; padding-left: 20px; }

